SELECT r.ret_reg, r.churn_flag, r.retain_engage_pivot, r.retain_loyalty_pivot
FROM retentionandinfluence r
LIMIT 10;

SELECT e.engage_reg, e.soc_int_score, e.engage_member_pivot, e.engage_activity_pivot
FROM engagement e
LIMIT 10;

SELECT f.user_registry, f.nick_label, f.tier_step, f.pts_val, f.reg_moment
FROM fans f
LIMIT 10;

SELECT m.member_reg, m.member_fan_pivot, m.memb_kind, m.memb_days, m.spend_usd
FROM membershipandspending m
LIMIT 10;

-- Check how many fans have retention records via engagement
SELECT COUNT(DISTINCT m.member_fan_pivot) as total_fans_with_member
FROM membershipandspending m;

-- Check how many engagement records link to membership
SELECT COUNT(*) FROM engagement e JOIN membershipandspending m ON e.engage_member_pivot = m.member_reg;

-- Check retentionandinfluence join path
SELECT r.ret_reg, r.churn_flag, r.retain_engage_pivot
FROM retentionandinfluence r 
LIMIT 5;

-- How many unique fans are linked through membership?
SELECT COUNT(DISTINCT member_fan_pivot) as total_fans_in_membership
FROM membershipandspending;

-- How many unique fans are linked through interactions?
SELECT COUNT(DISTINCT interact_fan_pivot) as total_fans_in_interactions
FROM interactions;

-- Total fans
SELECT COUNT(*) FROM fans;
